            } else if (this.level.getRandom().nextFloat() <= 0.11F){
                this.spawnAtLocation(itemStack);
            }
            this.dropInventory();
            this.remove(RemovalReason.KILLED);
        }
        this.hurtTime = 1;
        this.setYRot(this.deathRotation);
        this.setYBodyRot(this.deathRotation);
    }

